def group_rows(rows):
    groups = {}
    for row in rows:
        key = row["customer_id"]
        groups.setdefault(key, []).append(row)
    return groups

from collections import defaultdict

def group_rows_alternative(rows):
    groups = defaultdict(list)
    for row in rows:
        groups[row["customer_id"]].append(row)
    return dict(groups)
